```javascript
// Function to convert HL7 v2 encounter date to ISO 8601 format
function convertEncounterDateToISO(msg) {
    try {
        // Extract the encounter date from the HL7 message
        var encounterDate = msg['EVN']['EVN.3']['EVN.3.1'].toString();

        // Define a regular expression to match the HL7 v2 date format (YYYYMMDDHHMMSS)
        var regex = /^(\d{8})(\d{4})$/;
        var match = encounterDate.match(regex);

        if (!match) {
            throw new Error('Invalid encounter date format');
        }

        // Extract year, month, day, hour, minute, and second from the matched groups
        var year = match[1].substring(0, 4);
        var month = match[1].substring(4, 6);
        var day = match[1].substring(6, 8);
        var hour = match[2].substring(0, 2);
        var minute = match[2].substring(2, 4);
        var second = match[2].substring(4, 6);

        // Create a JavaScript Date object
        var date = new Date(year, month - 1, day, hour, minute, second);

        // Format the Date object into ISO 8601 format
        var isoDate = date.toISOString();

        return isoDate;
    } catch (e) {
        // Log the error and throw it to be handled by Mirth Connect
        logger.error('Error converting encounter date to ISO 8601: ' + e.message);
        throw e;
    }
}

// Example usage in a transformer script
var isoEncounterDate = convertEncounterDateToISO(msg);
channelMap.put('isoEncounterDate', isoEncounterDate);

// Log the converted date for debugging purposes
logger.info('Converted ISO 8601 encounter date: ' + isoEncounterDate);
```

### Explanation:
