import requests
import jwt
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
CLIENT_ID = "your_client_id"
PRIVATE_KEY_PATH = "path_to_your_private_key.pem"

def generate_jwt():
    # Generate JWT assertion
    payload = {
        "iss": CLIENT_ID,
        "aud": BASE_URL,
        "exp": datetime.utcnow() + timedelta(minutes=10),
        "jti": str(datetime.utcnow().timestamp()),
        "client_id": CLIENT_ID,
        "scope": "patient/*.read"
    }

    with open(PRIVATE_KEY_PATH, 'r') as key_file:
        private_key = key_file.read()

    token = jwt.encode(payload, private_key, algorithm='RS256')
    return token

def get_access_token(jwt_token):
    # Exchange JWT for access token
    url = f"{BASE_URL}/oauth2/token"
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": jwt_token
    }

    response = requests.post(url, headers=headers, data=data)
    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

def kick_off_bulk_export(access_token):
    # Kick-off bulk export
    url = f"{BASE_URL}/Patient/$export"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/fhir+json",
        "Prefer": "respond-async"
    }

    response = requests.get(url, headers=headers)
    if response.status_code == 202:
        return response.headers["Content-Location"]
    else:
        raise Exception(f"Failed to kick-off bulk export: {response.text}")

def poll_export_status(status_url, access_token):
    # Poll export status
    while True:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(status_url, headers=headers)
        if response.status_code == 200:
            status = response.json().get("status")
            if status == "completed":
                return response.json()
            elif status in ["failed", "cancelled"]:
                raise Exception(f"Export failed with status: {status}")
            else:
                print(f"Waiting for export to complete... Status: {status}")
                time.sleep(10)
        else:
            raise Exception(f"Failed to poll export status: {response.text}")

def download_ndjson_files(file_urls, access_token):
    # Download NDJSON files
    ndjson_data = []
    for file_url in file_urls:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(file_url, headers=headers)
        if response.status_code == 200:
            ndjson_data.extend(response.json())
        else:
            raise Exception(f"Failed to download NDJSON file: {response.text}")

    return ndjson_data

def process_ndjson_data(ndjson_data):
    # Process NDJSON data
    for resource in ndjson_data:
        print(resource)

def main():
    try:
        jwt_token = generate_jwt()
        access_token = get_access_token(jwt_token)

        status_url = kick_off_bulk_export(access_token)
        export_status = poll_export_status(status_url, access_token)
        file_urls = [link["url"] for link in export_status.get("output", [])]

        ndjson_data = download_ndjson_files(file_urls, access_token)
        process_ndjson_data(ndjson_data)

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

### Explanation:

1. **generate_jwt**: Generates a signed JWT assertion using the private key.
2. **get_access_token**: Exchanges the JWT for an access token from the token endpoint.
3. **kick_off_bulk_export**: Initiates the bulk export and returns the `Content-Location` header.
4. **poll_export_status**: Polls the status URL until the export completes or fails.
